; ============================================== sub step ====

step:
; ---- had = pending
        mov     ax, [pending]
        mov     [step__had], ax
; ---- a = keyAction( k )
        mov     ax, [step__k]
        mov     [keyAction__k], ax
        call    keyAction
        mov     al, [keyAction__ret]
