        jne     .L432                       ; unsigned ==
        mov     ax, [step__had]
        test    ax, ax
        jne     .L432                       ; unsigned ==
        mov     ax, [step__k]
        mov     [keyIsPrefix__k], ax
        call    keyIsPrefix
        mov     al, [keyIsPrefix__ret]
        xor     ah, ah                      ; bool -> u16
        test    ax, ax
        jz      .L432
; ---- pending = k
        mov     ax, [step__k]
        mov     [pending], ax
; ---- return
        ret
.L432:
; ---- pending = 0
        mov     word [pending], 0
; ---- if ( k == keyQuit ) {
