        mov     ax, [step__k]
        mov     [apply__k], ax
        call    apply
        ret

; ============================================== sub runKeys ====

runKeys:
; ---- for ( u16 i = 0; i < n; i++ ) {
        mov     word [runKeys__i], 0
.L446:
        mov     ax, [runKeys__i]
        mov     bx, [runKeys__n]
        cmp     ax, bx
