        mov     [step__k], ax
        call    step
.L447:
        inc     word [runKeys__i]
        jmp     .L446
.L448:
        ret

; ============================================== sub viewRow ====

viewRow:
; ---- for ( u16 i = 0; i < n; i++ ) {
        mov     word [viewRow__i], 0
.L456:
        mov     ax, [viewRow__i]
        mov     bx, [viewRow__n]
        cmp     ax, bx
        jae     .L458                       ; unsigned <
; ---- putChar( peek8( at + i ) )
        mov     ax, [viewRow__at]
        mov     bx, [viewRow__i]
        add     ax, bx
        mov     bx, ax
        mov     al, [bx]                    ; peek8 - unchecked, by design
        mov     [putChar__c], al            ; u8 -> u8, no widening
        call    putChar
.L457:
        inc     word [viewRow__i]
        jmp     .L456
.L458:
; ---- putChar( '|' )
        mov     byte [putChar__c], 124
        call    putChar
; ---- newline()
        call    newline
        ret

; ============================================== sub frame ====

frame:
; ---- viewRender()
        call    viewRender
; ---- putNumber( viewLine() )
        call    viewLine
        mov     ax, [viewLine__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
; ---- putNumber( viewCol() )
        call    viewCol
        mov     ax, [viewCol__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
; ---- putNumber( textLines() )
        call    textLines
        mov     ax, [textLines__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- newline()
        call    newline
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

